class Solution:
    def maxSumRangeQuery(self, nums: List[int], requests: List[List[int]]) -> int:
        n = len(nums)
        freq = [0] * n
        for l, r in requests:
            for i in range(l, r + 1):
                freq[i] += 1
        freq.sort(reverse=True)
        nums.sort(reverse=True)
        return sum(f * v for f, v in zip(freq, nums)) % (10**9 + 7)

