        n = len(nums)
        diff = [0] * (n + 1)
        for l, r in requests:
            diff[l] += 1
            diff[r + 1] -= 1
        freq, cur = [0] * n, 0
        for i in range(n):
            cur += diff[i]
            freq[i] = cur
        freq.sort(reverse=True)
        nums.sort(reverse=True)
        return sum(f * v for f, v in zip(freq, nums)) % (10**9 + 7)

